using Godot;
using System;
using System.Collections.Generic;
public partial class MigrationScene {
 readonly List<(Node3D Node,double Until)> fieldJets=new();
 ColorRect fieldFlash;double fieldFlashUntil;
 void FieldDetonationVisual(int kind,Vector3 at){ImpactParticles(at+Vector3.Up*.2f,kind is 2 or 3?new Color(.95f,.62f,.15f):kind==8?new Color(1,1,.9f):FieldColor(kind),24,.10f);if(kind is 2 or 3 or 8)EnemySound(at,3);if(kind==8&&Distance(player.Position,at)<10&&FieldLine(at,player.Position)){if(fieldFlash==null){fieldFlash=new ColorRect{MouseFilter=Control.MouseFilterEnum.Ignore,ZIndex=100,Size=GetViewport().GetVisibleRect().Size};hudRoot.AddChild(fieldFlash);}fieldFlashUntil=fieldTime+.65;}}
 [Rpc(MultiplayerApi.RpcMode.Authority,TransferMode=MultiplayerPeer.TransferModeEnum.Reliable)]void CoopFieldDetonation(int kind,Vector3 at){if(CoopClient)FieldDetonationVisual(kind,at);}
 void FlameJetVisual(Vector3 from,Vector3 direction){if(DisplayServer.GetName()=="headless")return;while(fieldJets.Count>=4){fieldJets[0].Node.QueueFree();fieldJets.RemoveAt(0);}var root=new Node3D{Position=from+direction*.6f};AddChild(root);for(int i=0;i<8;i++){float size=.09f+i*.045f;var flame=Ellipsoid(root,direction*(i*.65f),new(size,size,size*1.5f),new(1,.5f,.09f));flame.MaterialOverride=new StandardMaterial3D{AlbedoColor=new(1,.38f+i*.025f,.06f,.7f),EmissionEnabled=true,Emission=new(1,.2f,.02f),Transparency=BaseMaterial3D.TransparencyEnum.Alpha,ShadingMode=BaseMaterial3D.ShadingModeEnum.Unshaded};}fieldJets.Add((root,fieldTime+.18));}
 void TickFieldJets(){if(fieldFlash!=null){float alpha=(float)Math.Max(0,(fieldFlashUntil-fieldTime)*.75);fieldFlash.Color=new Color(1,1,.9f,alpha);fieldFlash.Visible=alpha>0;fieldFlash.Size=GetViewport().GetVisibleRect().Size;}for(int i=fieldJets.Count-1;i>=0;i--)if(fieldJets[i].Until<fieldTime){fieldJets[i].Node.QueueFree();fieldJets.RemoveAt(i);}}
 void AddFieldPackItems(List<PackEntry> items){for(int i=1;i<6;i++)if(game.Craft.ArrowStock[i]>0)items.Add(new(){Key="field-arrow/"+i,Kind="fieldkit",Index=i,Name=ExpeditionGame.ArrowNames[i],Count=game.Craft.ArrowStock[i],Description="Arrow payload / +"+ExpeditionGame.ArrowBonus[i]+" impact damage. Select in F3 before firing."});for(int i=0;i<10;i++)if(game.Craft.ThrowStock[i]>0)items.Add(new(){Key="field-throw/"+i,Kind="fieldkit",Index=100+i,Name=ExpeditionGame.ThrowableNames[i],Count=game.Craft.ThrowStock[i],Description="Select in F3; press G to throw. Fire and blast can hurt you."});for(int f=0;f<4;f++)if(game.Craft.ToolLevels[f]>0)items.Add(new(){Key="field-tool/"+f,Kind="fieldkit",Index=200+f*10+game.Craft.ToolLevels[f],Name=ExpeditionGame.HarvestToolName(f,game.Craft.ToolLevels[f]),Count=1,Tier=f==3?Math.Max(1,game.Craft.ToolLevels[f]-1):game.Craft.ToolLevels[f],Description=f==3?"Faster skinning; retains hide/meat trade-off.":"Select in F3, equip with T, aim and strike. Tool quality changes harvesting damage."});if(game.Craft.ScrapMetal>0)items.Add(new(){Key="raw-scrap",Kind="fieldkit",Index=400,Name="Raw scrap metal",Count=game.Craft.ScrapMetal,Description="Dismantled from cars. Used in iron tools, arrowheads, explosives and metal weapons. Distinct from higher-tier alloy scrap."});if(game.Craft.Glass>0)items.Add(new(){Key="salvage-glass",Kind="fieldkit",Index=401,Name="Salvaged glass containers",Count=game.Craft.Glass,Description="Recovered while dismantling cars; used for Molotovs and makeshift nail jars."});}
 void FieldKitItemArt(Node3D root,int id){if(id>=400){if(id==401)Tube(root,Vector3.Zero,new(0,.35f,0),.10f,new(.38f,.53f,.47f));else for(int i=0;i<3;i++)Bevel(root,new(i*.09f,.04f+i*.05f,0),new(.35f,.05f,.24f),Steel);return;}if(id>=200){int f=(id-200)/10,l=(id-200)%10;if(f==3){HuntingToolArt(root,1);if(l>=2)Bevel(root,new(0,.35f,0),new(.08f,.23f,.025f),l==2?new Color(.75f,.70f,.55f):Steel);}else{FieldHarvestToolArt(root,f,l);root.RotationDegrees=new(-60,0,0);root.Position=new(0,.45f,0);}return;}if(id>=100){FieldItemArt(root,id-100);return;}for(int i=0;i<3;i++){Tube(root,new(i*.06f-.06f,0,0),new(i*.06f-.06f,.55f,0),.008f,Wood);Bevel(root,new(i*.06f-.06f,.57f,0),new(.04f,.07f,.02f),id==5?new Color(.85f,.35f,.08f):id>=3?Steel: new Color(.55f,.52f,.43f));}}
 void FlamethrowerArt(Node3D root){Bevel(root,new(0,-.01f,-.18f),new(.15f,.18f,.40f),new(.25f,.31f,.23f));Tube(root,new(0,.01f,-.38f),new(0,.01f,-.95f),.04f,Steel);for(int i=0;i<5;i++)Tube(root,new(-.06f,-.03f,-.43f-i*.06f),new(.06f,-.03f,-.43f-i*.06f),.014f,Steel);Tube(root,new(-.12f,-.12f,.04f),new(-.12f,.16f,.04f),.085f,new(.55f,.35f,.13f));Tube(root,new(.09f,-.08f,-.03f),new(.09f,-.08f,-.86f),.012f,new(.37f,.24f,.13f));Bevel(root,new(0,-.14f,.01f),new(.06f,.19f,.07f),Wood);Ellipsoid(root,new(.09f,-.07f,-.88f),new(.018f,.025f,.035f),new(1,.5f,.13f));}
 [Rpc(MultiplayerApi.RpcMode.Authority,TransferMode=MultiplayerPeer.TransferModeEnum.Reliable)]void CoopFieldFlame(Vector3 from,Vector3 dir){if(CoopClient)FlameJetVisual(from,dir);}
}
